// Proposed command pattern:
interface ToolHandler {
  execute(args: Record<string, unknown>, ctx: ExecutorContext): Promise<ActionResult>;
}

const handlers: Map<string, ToolHandler> = new Map([
  ['generate_background', new GenerateBackgroundHandler()],
  ['magic_edit', new MagicEditHandler()],
  // etc.
]);

async executeToolCall(toolCall: ToolCall): Promise<ActionResult> {
  const handler = this.handlers.get(toolCall.name);
  if (!handler) return { success: false, error: `Unknown tool: ${toolCall.name}` };
  return handler.execute(toolCall.args, this.context);
}

